// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Отток по неделям, факт и прогноз (слой 2)
	// (GET /api/v1/analytics/churn-chart)
	GetChurnChart(w http.ResponseWriter, r *http.Request)
	// Сводка риска и ожидаемых потерь
	// (GET /api/v1/analytics/summary)
	GetSummary(w http.ResponseWriter, r *http.Request)
	// Журнал действий, новые сверху (аналитик, администратор)
	// (GET /api/v1/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Настройки входа для экрана входа (открыт)
	// (GET /api/v1/auth/config)
	GetAuthConfig(w http.ResponseWriter, r *http.Request)
	// Вход по логину и паролю (открыт)
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Завершение текущей сессии
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Текущий пользователь
	// (GET /api/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Возврат с OIDC-провайдера (слой 2, открыт)
	// (GET /api/v1/auth/oidc/callback)
	OidcCallback(w http.ResponseWriter, r *http.Request, params OidcCallbackParams)
	// Начало входа через OIDC (слой 2, открыт)
	// (GET /api/v1/auth/oidc/login)
	OidcLogin(w http.ResponseWriter, r *http.Request)
	// Клиенты с оценкой риска; фильтр и сортировка рейтинга
	// (GET /api/v1/customers)
	ListCustomers(w http.ResponseWriter, r *http.Request, params ListCustomersParams)
	// Очередь целиком в CSV (UTF-8 с BOM, разделитель `;`, десятичная запятая)
	// (GET /api/v1/customers/export.csv)
	ExportCustomers(w http.ResponseWriter, r *http.Request, params ExportCustomersParams)
	// Подробная оценка клиента: услуги, признаки с вкладом, деньги, действия с ценой
	// (GET /api/v1/customers/{id})
	GetCustomer(w http.ResponseWriter, r *http.Request, id CustomerId)
	// Взять клиента в работу (маркетолог, jury, администратор)
	// (POST /api/v1/customers/{id}/task)
	TakeCustomerTask(w http.ResponseWriter, r *http.Request, id CustomerId)
	// Swagger UI (открыт, файлы вшиты в бинарь)
	// (GET /api/v1/docs)
	Docs(w http.ResponseWriter, r *http.Request)
	// SSE-поток событий, например {"type":"recalculated","version":N}; ход потока событий эмулятора — event streamProgress с телом StreamState
	// (GET /api/v1/events)
	GetEvents(w http.ResponseWriter, r *http.Request)
	// Чувствительность очереди к весам признаков (аналитик, jury)
	// (GET /api/v1/model/sensitivity)
	GetModelSensitivity(w http.ResponseWriter, r *http.Request)
	// Действующие настройки и коэффициенты модели
	// (GET /api/v1/model/settings)
	GetModelSettings(w http.ResponseWriter, r *http.Request)
	// Изменение настроек с пересчётом; dryRun=true только считает последствия (аналитик)
	// (PATCH /api/v1/model/settings)
	PatchModelSettings(w http.ResponseWriter, r *http.Request, params PatchModelSettingsParams)
	// Контракт в JSON (открыт)
	// (GET /api/v1/openapi.json)
	OpenapiJson(w http.ResponseWriter, r *http.Request)
	// Контракт в YAML (открыт)
	// (GET /api/v1/openapi.yml)
	OpenapiYaml(w http.ResponseWriter, r *http.Request)
	// Правка баланса и бонуса счёта (аналитик)
	// (PATCH /api/v1/source/accounts/{id})
	PatchAccount(w http.ResponseWriter, r *http.Request, id AccountId)
	// Применить действия по клиентам в эмуляторе (аналитик)
	// (POST /api/v1/source/emulator/actions)
	EmulatorActions(w http.ResponseWriter, r *http.Request)
	// Состояние текущего или последнего прогона потока (аналитик, jury)
	// (GET /api/v1/source/emulator/stream)
	GetEmulatorStream(w http.ResponseWriter, r *http.Request)
	// Запустить поток событий пользователей над текущим снимком (аналитик, jury)
	// (POST /api/v1/source/emulator/stream)
	StartEmulatorStream(w http.ResponseWriter, r *http.Request)
	// Сдвиг времени эмулятора биллинга (аналитик)
	// (POST /api/v1/source/emulator/tick)
	EmulatorTick(w http.ResponseWriter, r *http.Request)
	// Пачка событий биллинга извне (аналитик, jury или сервисный токен источника)
	// (POST /api/v1/source/events)
	PostSourceEvents(w http.ResponseWriter, r *http.Request)
	// Включить или поставить на паузу опрос REST-биллинга (аналитик)
	// (PUT /api/v1/source/polling)
	SetSourcePolling(w http.ResponseWriter, r *http.Request)
	// Правка одной услуги (аналитик)
	// (PATCH /api/v1/source/services/{id})
	PatchService(w http.ResponseWriter, r *http.Request, id ServiceId)
	// Загрузка или полная замена снимка данных с пересчётом (аналитик или сервисный токен)
	// (PUT /api/v1/source/snapshot)
	PutSnapshot(w http.ResponseWriter, r *http.Request)
	// Версия снимка, возраст, проверки качества
	// (GET /api/v1/source/status)
	GetSourceStatus(w http.ResponseWriter, r *http.Request)
	// Задачи удержания с фильтрами; новые правки сверху
	// (GET /api/v1/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request, params ListTasksParams)
	// Кому можно назначить задачу
	// (GET /api/v1/tasks/assignees)
	ListTaskAssignees(w http.ResponseWriter, r *http.Request)
	// Задача с историей
	// (GET /api/v1/tasks/{taskId})
	GetTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// Изменить статус, ответственного, срок, заметку, итог (маркетолог, jury, администратор)
	// (PATCH /api/v1/tasks/{taskId})
	PatchTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// Записать контакт или заметку в историю (маркетолог, jury, администратор)
	// (POST /api/v1/tasks/{taskId}/events)
	AddTaskEvent(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// Проверка живости
	// (GET /healthz)
	Healthz(w http.ResponseWriter, r *http.Request, params HealthzParams)
	// Алиас /metrics (опечатка в тексте кейса)
	// (GET /metics)
	GetMetricsAlias(w http.ResponseWriter, r *http.Request)
	// Метрики Prometheus (токен сборщика или сессия)
	// (GET /metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// Проверка связи без кэша
	// (GET /ping)
	Ping(w http.ResponseWriter, r *http.Request, params PingParams)
	// Проверка связи без кэша, без тела ответа
	// (HEAD /ping)
	PingHead(w http.ResponseWriter, r *http.Request, params PingHeadParams)
	// Версия сборки
	// (GET /version)
	Version(w http.ResponseWriter, r *http.Request, params VersionParams)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// GetChurnChart operation middleware
func (siw *ServerInterfaceWrapper) GetChurnChart(w http.ResponseWriter, r *http.Request) {

	ctx := r.Context()

	ctx = context.WithValue(ctx, CookieAuthScopes, []string{})

	ctx = context.WithValue(ctx, BearerAuthScopes, []string{})

	r = r.WithContext(ctx)

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetChurnChart(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

